-- deploy-gate: deferred بقرار D03، يُطبَّق بعد توقيع لجنة المحتوى ومراجع قياسي، بعد 20261105150000 وقبل التفعيل
-- مولَّد بـ scripts/questions/build-v5_2.mjs من supabase/content/questions/v5.1 وscripts/questions/edits-v5_2.mjs
-- 102 صفًا يتغير، والدرجات ومواضع المفاتيح ثابتة. الحارس: لا قياس مبدوء على الأداتين، ونص كل صف
-- المتغير هو نص v5.1 (بصمة md5 للجذع والخيارات)، وإلا يُرفض الترحيل كله. آمن لإعادة التشغيل.
do $$ begin
  if exists (select 1 from leaders.assessments a join leaders.instruments i on i.id = a.instrument_id where i.key in ('baseline-v5', 'post-v3')) then
    raise exception 'v5.2: لأداتي v5 قياسات مبدوءة؛ لا تُعدَّل فقراتهما بعد ذلك';
  end if;
  if not exists (select 1 from leaders.schema_migrations where name = '20261105150000_leaders_v5_1_pre_activation') then
    raise exception 'v5.2: طبّق 20261105150000_leaders_v5_1_pre_activation.sql أولًا';
  end if;
end $$;

-- baseline-v5/M-S4
update leaders.questions q set text_ar = 'مشروع ممول من جهة حكومية أخرى، وتقارير التمويل التي تشترطها ترهق الفريق ولا تُستخدم داخليًا. ما المعالجة الأنسب؟', options = '[{"label":"التفاوض مع الجهة الممولة على تقرير فصلي بدل الشهري","score":2},{"label":"ربط مواعيد التقارير بمعالم القرار الداخلية","score":4},{"label":"إسناد التقارير لموظف متخصص بعيدًا عن الفريق","score":1},{"label":"دمج التقارير في تقرير سنوي واحد شامل","score":0}]'::jsonb, chapter_key = 'ch2', competency_ar = 'مواءمة متطلبات الجهة الممولة'
  from leaders.instruments i where i.id = q.instrument_id and i.key = 'baseline-v5' and q.code = 'M-S4'
  and ((q.text_ar = 'مشروع تنموي ممول من جهة مانحة، وتقارير المنحة ترهق الفريق ولا تُستخدم داخليًا. ما المعالجة الأنسب؟' and q.options = '[{"label":"التفاوض مع المانح على تقرير فصلي بدل الشهري","score":2},{"label":"ربط مواعيد التقارير بمعالم القرار الداخلية","score":4},{"label":"إسناد التقارير لموظف متخصص بعيدًا عن الفريق","score":1},{"label":"دمج التقارير في تقرير سنوي واحد شامل","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'مواءمة متطلبات المانح') or (q.text_ar = 'مشروع ممول من جهة حكومية أخرى، وتقارير التمويل التي تشترطها ترهق الفريق ولا تُستخدم داخليًا. ما المعالجة الأنسب؟' and q.options = '[{"label":"التفاوض مع الجهة الممولة على تقرير فصلي بدل الشهري","score":2},{"label":"ربط مواعيد التقارير بمعالم القرار الداخلية","score":4},{"label":"إسناد التقارير لموظف متخصص بعيدًا عن الفريق","score":1},{"label":"دمج التقارير في تقرير سنوي واحد شامل","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'مواءمة متطلبات الجهة الممولة'));
