  and ((q.text_ar = 'مشروع تنموي ممول من جهة مانحة، وتقارير المنحة ترهق الفريق ولا تُستخدم داخليًا. ما المعالجة الأنسب؟' and q.options = '[{"label":"التفاوض مع المانح على تقرير فصلي بدل الشهري","score":2},{"label":"ربط مواعيد التقارير بمعالم القرار الداخلية","score":4},{"label":"إسناد التقارير لموظف متخصص بعيدًا عن الفريق","score":1},{"label":"دمج التقارير في تقرير سنوي واحد شامل","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'مواءمة متطلبات المانح') or (q.text_ar = 'مشروع ممول من جهة حكومية أخرى، وتقارير التمويل التي تشترطها ترهق الفريق ولا تُستخدم داخليًا. ما المعالجة الأنسب؟' and q.options = '[{"label":"التفاوض مع الجهة الممولة على تقرير فصلي بدل الشهري","score":2},{"label":"ربط مواعيد التقارير بمعالم القرار الداخلية","score":4},{"label":"إسناد التقارير لموظف متخصص بعيدًا عن الفريق","score":1},{"label":"دمج التقارير في تقرير سنوي واحد شامل","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'مواءمة متطلبات الجهة الممولة'));
