  and ((q.text_ar = 'جهة تطلق برنامجًا متطلباته واضحة ومستقرة، وتشترط اعتماد اللجنة قبل كل مرحلة وصرف الميزانية على دفعات. أي نهج أنسب لإدارته؟' and q.options = '[{"label":"نهج تنبؤي بمراحل وبوابات اعتماد","score":4},{"label":"نهج تكيفي بدورات قصيرة وأولويات متغيرة","score":0},{"label":"نهج هجين يبدأ تكيفيًا ثم يصبح تنبؤيًا","score":0},{"label":"إدارة تشغيلية بمؤشرات أداء شهرية","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch1' and q.competency_ar is not distinct from 'اختيار نهج الإدارة') or (q.text_ar = 'جهة تطلق برنامجًا متطلباته واضحة ومستقرة، وتشترط اعتماد اللجنة قبل كل مرحلة وصرف الميزانية على دفعات. أي نهج أنسب لإدارته؟' and q.options = '[{"label":"نهج تنبؤي بمراحل متتابعة وبوابات اعتماد","score":4},{"label":"نهج تكيفي بدورات قصيرة وأولويات متغيرة","score":0},{"label":"نهج هجين يبدأ تكيفيًا ثم يصبح تنبؤيًا","score":0},{"label":"إدارة تشغيلية بمؤشرات أداء شهرية","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch1' and q.competency_ar is not distinct from 'اختيار نهج الإدارة'));
