  and ((q.text_ar = 'انضم إليك موظف من إدارة أخرى، خبرته طويلة في المشتريات لكنه يدير مشروعًا لأول مرة ويتردد في اتخاذ القرارات. ما الأسلوب الأنسب معه في أول مهمة؟' and q.options = '[{"label":"تفويضه المهمة كاملة اعتمادًا على خبرته الطويلة","score":1},{"label":"تشجيعه وترك طريقة التنفيذ له ليبني ثقته","score":1},{"label":"خطوات واضحة ومتابعة قريبة مع شرح سبب كل خطوة","score":4},{"label":"إسناد المهمة لزميل أقدم ليتعلم منه بالمشاهدة","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch4' and q.competency_ar is not distinct from 'توجيه عضو جديد') or (q.text_ar = 'انضم إليك موظف من إدارة أخرى، خبرته طويلة في المشتريات لكنه يدير مشروعًا لأول مرة ويتردد في اتخاذ القرارات. ما الأسلوب الأنسب معه في أول مهمة؟' and q.options = '[{"label":"تفويضه المهمة كاملة اعتمادًا على خبرته الطويلة","score":1},{"label":"تشجيعه وترك طريقة التنفيذ له ليبني ثقته","score":1},{"label":"خطوات واضحة ومتابعة قريبة مع شرح سببها","score":4},{"label":"إسناد المهمة لزميل أقدم ليتعلم منه بالمشاهدة","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch4' and q.competency_ar is not distinct from 'توجيه عضو جديد'));
