  and ((q.text_ar = 'إدارتك وإدارة أخرى تحتاجان قاعة التدريب الوحيدة في الأسبوع نفسه، ولكل منهما برنامج معتمد، والعلاقة بينكما جيدة. ما الأنسب؟' and q.options = '[{"label":"لقاء مع مدير الإدارة الأخرى لبحث بدائل تلبي البرنامجين","score":4},{"label":"اقتراح تقسيم أيام الأسبوع بين البرنامجين بالتناوب","score":2},{"label":"رفع الأمر إلى من يملك صلاحية تخصيص القاعة ليحسمه بينكما","score":1},{"label":"نقل برنامجك إلى موعد لاحق حفاظًا على العلاقة","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch4' and q.competency_ar is not distinct from 'إدارة الخلاف') or (q.text_ar = 'إدارتك وإدارة أخرى تحتاجان قاعة التدريب الوحيدة في الأسبوع نفسه، ولكل منهما برنامج معتمد، والعلاقة بينكما جيدة. ما الأنسب؟' and q.options = '[{"label":"لقاء مدير الإدارة الأخرى لبحث بدائل تلبيهما","score":4},{"label":"اقتراح تقسيم أيام الأسبوع بين البرنامجين بالتناوب","score":2},{"label":"رفع الأمر إلى من يملك صلاحية تخصيص القاعة ليحسمه بينكما","score":1},{"label":"نقل برنامجك إلى موعد لاحق حفاظًا على العلاقة","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch4' and q.competency_ar is not distinct from 'إدارة الخلاف'));
