  and ((q.text_ar = 'برنامج لمحو الأمية معالمه: توقيع المنحة، وتعيين المعلمين، وافتتاح الفصول، والتقرير الختامي. ما التعديل الأهم على سجله؟' and q.options = '[{"label":"إضافة معلم لتسلم الشريك المحلي إدارة الفصول كاملة","score":2},{"label":"إضافة معلم لتقرير منتصف المدة إلى المانح","score":1},{"label":"تقسيم معلم افتتاح الفصول بحسب المناطق","score":0},{"label":"إضافة معلم يتحقق من تحسن القراءة لدى الدارسين","score":4}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'أنواع المعالم في السياق التنموي') or (q.text_ar = 'برنامج لمحو الأمية معالمه: اعتماد التمويل، وتعيين المعلمين، وافتتاح الفصول، والتقرير الختامي. ما التعديل الأهم على سجله؟' and q.options = '[{"label":"إضافة معلم لتسلم الجهة المحلية إدارة الفصول كاملة","score":2},{"label":"إضافة معلم لتقرير منتصف المدة إلى الجهة الممولة","score":1},{"label":"تقسيم معلم افتتاح الفصول بحسب المناطق","score":0},{"label":"إضافة معلم يتحقق من تحسن القراءة لدى الدارسين","score":4}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'أنواع المعالم في مشاريع القطاع العام'));
-- post-v3/M-S13B
update leaders.questions q set text_ar = 'مشروع إيواء طارئ بعد سيول، وأول معالمه إكمال المناقصة بعد ستة أسابيع. ما الخلل الأبرز في سجل معالمه؟', options = '[{"label":"غياب معلم لتسلم الجهة المحلية إدارة مراكز الإيواء","score":2},{"label":"غياب معلم استجابة يقيس سرعة الوصول إلى المتضررين","score":4},{"label":"غياب معلم لتقرير الجهة الممولة الدوري عن الصرف","score":1},{"label":"تأخر معلم المناقصة عن موعده المعتاد في إجراءات الجهة","score":0}]'::jsonb, chapter_key = 'ch2', competency_ar = 'أنواع المعالم في مشاريع القطاع العام'
  from leaders.instruments i where i.id = q.instrument_id and i.key = 'post-v3' and q.code = 'M-S13B'
  and ((q.text_ar = 'مشروع إيواء طارئ بعد سيول، وأول معالمه إكمال المناقصة بعد ستة أسابيع. ما الخلل الأبرز في سجل معالمه؟' and q.options = '[{"label":"غياب معلم لتسلم الشريك المحلي إدارة مراكز الإيواء","score":2},{"label":"غياب معلم استجابة يقيس سرعة الوصول إلى المتضررين","score":4},{"label":"غياب معلم لتقرير المانح الدوري عن الصرف","score":1},{"label":"تأخر معلم المناقصة عن موعده المعتاد في إجراءات الجهة","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'أنواع المعالم في السياق التنموي') or (q.text_ar = 'مشروع إيواء طارئ بعد سيول، وأول معالمه إكمال المناقصة بعد ستة أسابيع. ما الخلل الأبرز في سجل معالمه؟' and q.options = '[{"label":"غياب معلم لتسلم الجهة المحلية إدارة مراكز الإيواء","score":2},{"label":"غياب معلم استجابة يقيس سرعة الوصول إلى المتضررين","score":4},{"label":"غياب معلم لتقرير الجهة الممولة الدوري عن الصرف","score":1},{"label":"تأخر معلم المناقصة عن موعده المعتاد في إجراءات الجهة","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'أنواع المعالم في مشاريع القطاع العام'));
