update leaders.questions q set text_ar = 'أي سؤال يخص «الاستدامة» عند تقييم برنامج تنموي؟', options = '[{"label":"هل تستمر فوائده بعد انتهاء تمويله؟","score":4},{"label":"هل حقق أهدافه المعلنة في موعدها؟","score":0},{"label":"هل تناسب أهدافه حاجات المستفيدين؟","score":0},{"label":"هل وُظفت موارده بأقل تكلفة ممكنة؟","score":0}]'::jsonb, chapter_key = 'ch1', competency_ar = 'أسئلة تقييم التدخل'
  from leaders.instruments i where i.id = q.instrument_id and i.key = 'post-v3' and q.code = 'I-K12'
  and ((q.text_ar = 'أي سؤال يخص «الاستدامة» عند تقييم برنامج تنموي؟' and q.options = '[{"label":"هل تستمر فوائده بعد انتهاء تمويله؟","score":4},{"label":"هل حقق أهدافه المعلنة في موعدها؟","score":0},{"label":"هل تناسب أهدافه حاجات المستفيدين؟","score":0},{"label":"هل استُخدمت موارده بأقل تكلفة ممكنة؟","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch1' and q.competency_ar is not distinct from 'أسئلة تقييم التدخل') or (q.text_ar = 'أي سؤال يخص «الاستدامة» عند تقييم برنامج تنموي؟' and q.options = '[{"label":"هل تستمر فوائده بعد انتهاء تمويله؟","score":4},{"label":"هل حقق أهدافه المعلنة في موعدها؟","score":0},{"label":"هل تناسب أهدافه حاجات المستفيدين؟","score":0},{"label":"هل وُظفت موارده بأقل تكلفة ممكنة؟","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch1' and q.competency_ar is not distinct from 'أسئلة تقييم التدخل'));
