update leaders.questions q set text_ar = 'متى يمكن الحكم على أن منفعة مشروع قد تحققت فعلًا؟', options = '[{"label":"حين يُسلَّم المخرج ويُوقَّع محضر استلامه رسميًا","score":0},{"label":"حين يُقاس التغيير المستهدف بعد الاستخدام","score":4},{"label":"حين يُغلق المشروع ضمن ميزانيته وموعده","score":0},{"label":"حين يعتمد الراعي تقرير إغلاق المشروع بشكل نهائي","score":0}]'::jsonb, chapter_key = 'ch1', competency_ar = 'تحقق المنافع بعد التسليم'
  from leaders.instruments i where i.id = q.instrument_id and i.key = 'post-v3' and q.code = 'I-K13'
  and ((q.text_ar = 'متى يمكن الحكم على أن منفعة مشروع قد تحققت فعلًا؟' and q.options = '[{"label":"حين يُسلَّم المخرج ويُوقَّع محضر استلامه رسميًا","score":0},{"label":"حين يُقاس التغيير المستهدف بعد الاستخدام","score":4},{"label":"حين يُغلق المشروع ضمن ميزانيته وموعده","score":0},{"label":"حين يعتمد الراعي تقرير الإغلاق النهائي","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch1' and q.competency_ar is not distinct from 'تحقق المنافع بعد التسليم') or (q.text_ar = 'متى يمكن الحكم على أن منفعة مشروع قد تحققت فعلًا؟' and q.options = '[{"label":"حين يُسلَّم المخرج ويُوقَّع محضر استلامه رسميًا","score":0},{"label":"حين يُقاس التغيير المستهدف بعد الاستخدام","score":4},{"label":"حين يُغلق المشروع ضمن ميزانيته وموعده","score":0},{"label":"حين يعتمد الراعي تقرير إغلاق المشروع بشكل نهائي","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch1' and q.competency_ar is not distinct from 'تحقق المنافع بعد التسليم'));
