update leaders.questions q set text_ar = 'يقترح عليك مزود اعتماد منهجيته التجارية في قياس الأثر لأنها «الأشهر في السوق». ما الأنسب؟', options = '[{"label":"تسأل عن أصلها في مدارس التقييم وتأخذ ما يناسب أثرك وجمهورك","score":4},{"label":"تجربها على برنامج واحد قبل تعميمها على بقية البرامج في الجهة","score":2},{"label":"ترفضها وتلتزم بمعايير DAC لأنها دولية محايدة ومعروفة","score":1},{"label":"تعتمدها كما هي ما دامت مستخدمة لدى جهات كبرى معروفة في السوق","score":0}]'::jsonb, chapter_key = 'ch1', competency_ar = 'اختيار نموذج القياس'
  from leaders.instruments i where i.id = q.instrument_id and i.key = 'post-v3' and q.code = 'I-S12B'
  and ((q.text_ar = 'يقترح عليك مزود اعتماد منهجيته التجارية في قياس الأثر لأنها «الأشهر في السوق». ما الأنسب؟' and q.options = '[{"label":"تسأل عن أصلها في مدارس التقييم وتأخذ ما يناسب أثرك وجمهورك","score":4},{"label":"تجربها على برنامج واحد قبل تعميمها على بقية البرامج في الجهة","score":2},{"label":"ترفضها وتلتزم بمعايير DAC لأنها دولية محايدة ومعروفة","score":1},{"label":"تعتمدها كما هي ما دامت مستخدمة لدى جهات كبيرة معروفة","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch1' and q.competency_ar is not distinct from 'اختيار نموذج القياس') or (q.text_ar = 'يقترح عليك مزود اعتماد منهجيته التجارية في قياس الأثر لأنها «الأشهر في السوق». ما الأنسب؟' and q.options = '[{"label":"تسأل عن أصلها في مدارس التقييم وتأخذ ما يناسب أثرك وجمهورك","score":4},{"label":"تجربها على برنامج واحد قبل تعميمها على بقية البرامج في الجهة","score":2},{"label":"ترفضها وتلتزم بمعايير DAC لأنها دولية محايدة ومعروفة","score":1},{"label":"تعتمدها كما هي ما دامت مستخدمة لدى جهات كبرى معروفة في السوق","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch1' and q.competency_ar is not distinct from 'اختيار نموذج القياس'));
