update leaders.questions q set text_ar = 'تتراكم عليك تكليفات عاجلة كل يوم فتتأخر المهام الأهم. ما الخلل الذي تصفه هذه الحالة؟', options = '[{"label":"ضعف التفويض إلى أعضاء الفريق القادرين","score":0},{"label":"غياب جدول زمني مكتوب للمهام","score":0},{"label":"كثرة الاجتماعات التي تستهلك معظم اليوم","score":0},{"label":"إدارة الأولويات بحسب الإلحاح لا الأهمية","score":4}]'::jsonb, chapter_key = 'ch2', competency_ar = 'إغلاق حلقة التكليف'
  from leaders.instruments i where i.id = q.instrument_id and i.key = 'post-v3' and q.code = 'L-K13B'
  and ((q.text_ar = 'تتراكم عليك تكليفات عاجلة كل يوم فتتأخر المهام الأهم. ما الخلل الذي تصفه هذه الحالة؟' and q.options = '[{"label":"ضعف التفويض إلى أعضاء الفريق القادرين","score":0},{"label":"غياب جدول زمني مكتوب للمهام","score":0},{"label":"كثرة الاجتماعات التي تستهلك ساعات اليوم","score":0},{"label":"إدارة الأولويات بحسب الإلحاح لا الأهمية","score":4}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'إغلاق حلقة التكليف') or (q.text_ar = 'تتراكم عليك تكليفات عاجلة كل يوم فتتأخر المهام الأهم. ما الخلل الذي تصفه هذه الحالة؟' and q.options = '[{"label":"ضعف التفويض إلى أعضاء الفريق القادرين","score":0},{"label":"غياب جدول زمني مكتوب للمهام","score":0},{"label":"كثرة الاجتماعات التي تستهلك معظم اليوم","score":0},{"label":"إدارة الأولويات بحسب الإلحاح لا الأهمية","score":4}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'إغلاق حلقة التكليف'));

do $$ declare n int; begin
  select count(*) into n from leaders.questions q join leaders.instruments i on i.id = q.instrument_id where false
    or (i.key = 'baseline-v5' and q.code = 'M-S4' and (q.text_ar = 'مشروع ممول من جهة حكومية أخرى، وتقارير التمويل التي تشترطها ترهق الفريق ولا تُستخدم داخليًا. ما المعالجة الأنسب؟' and q.options = '[{"label":"التفاوض مع الجهة الممولة على تقرير فصلي بدل الشهري","score":2},{"label":"ربط مواعيد التقارير بمعالم القرار الداخلية","score":4},{"label":"إسناد التقارير لموظف متخصص بعيدًا عن الفريق","score":1},{"label":"دمج التقارير في تقرير سنوي واحد شامل","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch2' and q.competency_ar is not distinct from 'مواءمة متطلبات الجهة الممولة'))
    or (i.key = 'baseline-v5' and q.code = 'M-S2' and (q.text_ar = 'في جلسة بوابة مرحلة: المشروع متأخر ثلاثة أسابيع، ومبرر الاستمرار قائم، والمخاطر معروفة. ما القرار الأنسب؟' and q.options = '[{"label":"إعادة عقد الجلسة بعد أسبوعين وقد حُدّث الجدول","score":1},{"label":"استمرار مع خطة تصحيح تُعرض في الاجتماع الدوري القادم","score":2},{"label":"استمرار مع طلب اعتماد خط أساس معدل بالتاريخ الجديد","score":1},{"label":"استمرار مع خطة تصحيح ومعلم مراجعة خلال أسبوعين","score":4}]'::jsonb and q.chapter_key is not distinct from 'ch4' and q.competency_ar is not distinct from 'قرار البوابة'))
    or (i.key = 'baseline-v5' and q.code = 'M-S2B' and (q.text_ar = 'في مراجعة مرحلية: المشروع ضمن الموعد، لكن دراسة حديثة تظهر أن الطلب على الخدمة أقل بكثير مما بُني عليه المبرر. ما القرار الأنسب؟' and q.options = '[{"label":"الاستمرار كما هو مع تحديث دراسة الطلب في المرحلة القادمة","score":2},{"label":"الاستمرار لأن الأداء ضمن الخطة والميزانية المعتمدتين","score":1},{"label":"عرض المبرر المحدث على اللجنة لتقرر الاستمرار أو التعديل","score":4},{"label":"تسريع التنفيذ لإطلاق الخدمة قبل أن يتراجع الطلب أكثر","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch4' and q.competency_ar is not distinct from 'قرار البوابة'))
    or (i.key = 'baseline-v5' and q.code = 'M-S5B' and (q.text_ar = 'بعد اعتماد خطة مشروع لتطوير نظام داخلي، طلبت إدارة مستفيدة ربطه بنظام آخر لم يكن في النطاق. ما التصرف الأنسب؟' and q.options = '[{"label":"تقديم طلب تغيير يبيّن أثر الربط على الوقت والتكلفة","score":4},{"label":"تسجيل الطلب ودراسته ضمن المرحلة الثانية من المشروع","score":2},{"label":"تنفيذ الربط إن قدّر الفريق أنه لا يؤخر التسليم","score":1},{"label":"الاتفاق مع الإدارة المستفيدة مباشرة على تنفيذه","score":0}]'::jsonb and q.chapter_key is not distinct from 'ch3' and q.competency_ar is not distinct from 'ضبط تغيير النطاق'))
    or (i.key = 'baseline-v5' and q.code = 'M-S6' and (q.text_ar = 'أبلغك المورد أن تسليم مكون رئيسي سيتأخر ستة أسابيع، وهذا الخطر مسجل مسبقًا مع خطة استجابة. ما أول خطوة؟' and q.options = '[{"label":"تفعيل خطة الاستجابة المسجلة وإبلاغ أصحاب القرار","score":4},{"label":"مطالبة المورد بخطة تعافٍ مكتوبة قبل تحديث الجدول","score":2},{"label":"تحديث الجدول بالتاريخ الجديد وذكره في التقرير الشهري","score":1},{"label":"مطالبة المورد بغرامة التأخير المنصوص عليها في العقد","score":1}]'::jsonb and q.chapter_key is not distinct from 'ch4' and q.competency_ar is not distinct from 'الاستجابة للمخاطر'))
    or (i.key = 'baseline-v5' and q.code = 'M-S6B' and (q.text_ar = 'قبل إطلاق خدمة بأسبوع تحقق خطر مسجل: انتقل الفريق التقني الرئيسي إلى مشروع آخر، وخطة الاستجابة تنص على فريق مساند. ما أول خطوة؟' and q.options = '[{"label":"طلب إعادة الفريق الأصلي من المشروع الآخر","score":1},{"label":"تأجيل الإطلاق أسبوعين لتهيئة فريق جديد من الداخل","score":1},{"label":"تفعيل الفريق المساند وإبلاغ أصحاب القرار","score":4},{"label":"تقييم قدرة الفريق المساند ثم إبلاغ أصحاب القرار لاحقًا","score":2}]'::jsonb and q.chapter_key is not distinct from 'ch4' and q.competency_ar is not distinct from 'الاستجابة للمخاطر'))
